steps.css:
body {
  max-width: 360px;
  margin: 36px auto;
  padding: 28px;
  font-family: Arial, sans-serif;
  color: #332449;
  background: #fff4f7;
  border: 2px solid #ffd6e4;
  border-radius: 24px;
  text-align: center;
}

h1 { color: #a72962; }

p {
  font-size: 1.25rem;
  font-weight: bold;
}

button {
  padding: 12px 24px;
  color: white;
  background: #d93b79;
  border: 0;
  border-radius: 999px;
  font-size: 1rem;
  cursor: pointer;
}

button:hover { background: #a72962; }

